/**
 * Name the pool the unit connects to (#101, a slice of #85), the way mempool
 * names pools: from its MIT dataset (ui/pools.json, generated by
 * dev/gen-pools.mjs). A stratum host matches a pool when it is the pool's own
 * domain or ends with it on a label boundary. Local and private hosts never
 * match: a pool on the LAN is the operator's own, and is shown by its host.
 */
const PRIVATE = [/^localhost$/, /\.local$/, /\.lan$/, /\.home\.arpa$/, /^\[?[0-9a-f:]*:[0-9a-f:]*\]?$/, /^\d{1,3}(\.\d{1,3}){3}$/];

export function identifyPool(host, data) {
  if (!host || !data || !Array.isArray(data.pools)) return null;
  const h = String(host).toLowerCase().replace(/\.$/, '');
  if (PRIVATE.some((re) => re.test(h))) return null;
  let best = null;
  for (const p of data.pools) {
    if (!p?.domain) continue;
    if ((h === p.domain || h.endsWith(`.${p.domain}`)) && (!best || p.domain.length > best.domain.length)) best = p;
  }
  return best;
}

/** Two letters for a pool with no cleared logo: initials, else the first two characters. */
export function monogram(name) {
  const words = String(name || '').split(/[^A-Za-z0-9]+/).filter(Boolean);
  if (!words.length) return '?';
  return (words.length > 1 ? words[0][0] + words[1][0] : words[0].slice(0, 2)).toUpperCase();
}
